import{_ as a,o,c as i,a2 as t}from"./chunks/framework.CqGPl1zp.js";const l="/newx-doc/assets/%E5%B7%A5%E4%BD%9C%E5%8F%B0.C5598Mxc.png",_=JSON.parse('{"title":"移动端 MES","description":"","frontmatter":{},"headers":[],"relativePath":"mes/mobile.md","filePath":"mes/mobile.md","lastUpdated":null}'),r={name:"mes/mobile.md"};function s(d,e,c,n,u,p){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="移动端-mes" tabindex="-1">移动端 MES <a class="header-anchor" href="#移动端-mes" aria-label="Permalink to &quot;移动端 MES&quot;">​</a></h1><p>友情提示</p><p>本文讲解 yudao 移动端（uni-app 版）的 MES 系统，重点说清楚两件事：MES 模块<strong>已经提供手机端</strong>、当前支持的<strong>主要功能</strong>。</p><ul><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-uniapp" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-uniapp</a>，基于 <code>uni-app</code> + <code>Vue3</code> + <code>wot-ui</code> 实现，支持 H5、微信小程序等多端。</li><li>后端：复用 PC 端同一套 <code>yudao-module-mes</code> 模块与 <code>/mes/**</code> 接口，移动端只是换了一层 UI。</li></ul><h2 id="_1-移动端功能" tabindex="-1">1. 移动端功能 <a class="header-anchor" href="#_1-移动端功能" aria-label="Permalink to &quot;1. 移动端功能&quot;">​</a></h2><ul><li>基础与生产：物料、客户、供应商、车间、工单、排产、报工、工艺等。</li><li>仓储与质量：入出库、领退料、库存、条码、批次、IQC、IPQC、OQC、RQC 等。</li><li>设备与排班：设备台账、点检保养、维修、班组、排班计划、工具台账等。</li></ul><p><img src="'+l+'" alt="MES 移动端"></p><h2 id="_2-启动与发布" tabindex="-1">2. 启动与发布 <a class="header-anchor" href="#_2-启动与发布" aria-label="Permalink to &quot;2. 启动与发布&quot;">​</a></h2><ul><li>启动：参考 <a href="./../quick-start-front">《快速启动【前端】》</a> 文档的「1.4 Vue3 + uni-app 版本」小节。</li><li>发布：参考 <a href="./../admin-uniapp/deploy">《运行发布》</a> 文档。</li></ul><p>启动完成后，在工作台选择「MES 系统」即可进入。</p><h2 id="_3-代码位置" tabindex="-1">3. 代码位置 <a class="header-anchor" href="#_3-代码位置" aria-label="Permalink to &quot;3. 代码位置&quot;">​</a></h2><ul><li>页面：<code>src/pages-mes/</code>、<code>src/pages-statistics/mes/</code></li><li>接口：<code>src/api/mes/</code></li></ul>',12)])])}const h=a(r,[["render",s]]);export{_ as __pageData,h as default};
